// ── Abstract base class ──────────────────────────────────────────
class ReportGenerator {
  // TEMPLATE METHOD — do not override
  generate(data) {
    const raw       = this.fetchData(data);
    const formatted = this.formatData(raw);
    this.beforeWrite();                    // hook
    const result    = this.writeOutput(formatted);
    this.afterWrite();                     // hook
    return result;
  }

  // Default implementation — may be overridden
  fetchData(data) { return data; }

  // Abstract steps — MUST be overridden
  formatData(raw) { throw new Error('formatData() must be implemented'); }
  writeOutput(content) { throw new Error('writeOutput() must be implemented'); }

  // Hooks — optional, no-op by default
  beforeWrite() {}
  afterWrite()  {}
}

// ── Concrete: CSV ─────────────────────────────────────────────────
class CsvReport extends ReportGenerator {
  formatData(rows) {
    const header = Object.keys(rows[0]).join(',');
    const body   = rows.map(r => Object.values(r).join(',')).join('\n');
    return `${header}\n${body}`;
  }

  writeOutput(content) {
    console.log('[CSV] Writing to report.csv');
    return `FILE:report.csv\n${content}`;
  }
}

// ── Concrete: HTML ────────────────────────────────────────────────
class HtmlReport extends ReportGenerator {
  formatData(rows) {
    const ths  = Object.keys(rows[0]).map(k => `<th>${k}</th>`).join('');
    const body = rows.map(r =>
      `<tr>${Object.values(r).map(v => `<td>${v}</td>`).join('')}</tr>`
    ).join('\n');
    return `<table><thead><tr>${ths}</tr></thead><tbody>\n${body}\n</tbody></table>`;
  }

  writeOutput(content) {
    console.log('[HTML] Writing to report.html');
    return `FILE:report.html\n${content}`;
  }

  // Override hook
  beforeWrite() { console.log('[HTML] Validating HTML structure before write...'); }
}

// ── Usage ─────────────────────────────────────────────────────────
const dataset = [
  { name: 'Alice', sales: 120, region: 'APAC' },
  { name: 'Bob',   sales: 98,  region: 'EMEA' },
];

const csv  = new CsvReport();
console.log(csv.generate(dataset));

const html = new HtmlReport();
console.log(html.generate(dataset));

// ── Template Method skeleton ──────────────────────────────────────
class AbstractProcessor {
  // Template method — fixed skeleton
  process(input) {
    const validated  = this.validate(input);   // abstract
    const transformed = this.transform(validated); // abstract
    this.onComplete(transformed);              // hook
    return transformed;
  }

  validate(input)      { throw new Error('validate() required'); }
  transform(data)      { throw new Error('transform() required'); }
  onComplete(result)   { /* optional hook */ }
}

// ── Strategy comparison: same goal, composition vs inheritance ───

// Template Method — inheritance
class UpperCaseProcessor extends AbstractProcessor {
  validate(s)    { if (typeof s !== 'string') throw new TypeError('String required'); return s; }
  transform(s)   { return s.toUpperCase(); }
  onComplete(r)  { console.log('[Hook] Processed:', r); }
}

// Strategy — composition
const upperCaseStrategy = {
  validate:  (s) => { if (typeof s !== 'string') throw new TypeError('String required'); return s; },
  transform: (s) => s.toUpperCase(),
};
function process(input, strategy) {
  const validated  = strategy.validate(input);
  return strategy.transform(validated);
}

new UpperCaseProcessor().process('hello'); // Template Method
console.log(process('hello', upperCaseStrategy)); // Strategy
// Both produce 'HELLO' — different structural trade-offs
